using System;using System.IO;using System.IO.Compression;using System.Text;using System.Drawing;using System.Drawing.Imaging;
namespace EanEtikety {
public static class JobOutput {
 public static Bitmap Raster(VectorScene scene,double dpi){int w=Math.Max(1,(int)Math.Round(scene.Width*dpi/25.4)),h=Math.Max(1,(int)Math.Round(scene.Height*dpi/25.4));if((long)w*h>60000000)throw new InvalidOperationException(Loc.T("Výstup je príliš veľký. Znížte DPI."));var b=new Bitmap(w,h,PixelFormat.Format24bppRgb);b.SetResolution((float)dpi,(float)dpi);try{using(var g=Graphics.FromImage(b)){g.Clear(Color.White);scene.Draw(g,new RectangleF(0,0,w,h),false);}return b;}catch{b.Dispose();throw;}}
 public static void Export(string path,string format,OutputPlan plan,double dpi){if(format=="pdf"){SceneOutput.Pdf(path,plan);return;}if(format=="docx"){Engine.DocxPlan(path,plan);return;}if(format=="svg"){if(plan.PageCount==1){using(var s=plan.Scene(0))File.WriteAllText(path,SceneOutput.Svg(s,new RectangleF(0,0,(float)plan.Width,(float)plan.Height)),new UTF8Encoding(false));}else using(var fs=File.Create(path))using(var zip=new ZipArchive(fs,ZipArchiveMode.Create))for(int page=0;page<plan.PageCount;page++)using(var s=plan.Scene(page))using(var w=new StreamWriter(zip.CreateEntry("page-"+(page+1).ToString("D4")+".svg").Open(),new UTF8Encoding(false)))w.Write(SceneOutput.Svg(s,new RectangleF(0,0,(float)plan.Width,(float)plan.Height)));return;}if(format!="zpl")throw new ArgumentException("format");using(var output=new StreamWriter(path,false,Encoding.ASCII))for(int page=0;page<plan.PageCount;page++)using(var scene=plan.Scene(page))using(var b=Raster(scene,dpi)){var bytes=Engine.Packed(b,true);int stride=(b.Width+7)/8,rows=Math.Max(1,60000/stride);output.Write("^XA\n^PW"+b.Width+"\n^LL"+b.Height+"\n^LH0,0\n");for(int y=0;y<b.Height;y+=rows){int count=Math.Min(rows,b.Height-y)*stride;output.Write("^FO0,"+y+"^GFA,"+count+","+count+","+stride+",");for(int i=0;i<count;i++)output.Write(bytes[y*stride+i].ToString("X2"));output.Write("^FS\n");}output.Write("^PQ1,0,1,N\n^XZ\n");}}
}
}
